// CBET Fundamentals practice deck (v24). Original exam-style items mapped to the AAMI CBET outline. Data only.
LSA.deck({
  id: "cbet", name: "CBET Fundamentals", icon: "🔌",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "openstax-up2": ["OpenStax University Physics Volume 2", "https://openstax.org/books/university-physics-volume-2/pages/1-introduction"],
    "openstax-ap": ["OpenStax Anatomy and Physiology 2e", "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-introduction"],
    "hhs-hipaa": ["HHS: HIPAA for Professionals", "https://www.hhs.gov/hipaa/for-professionals/index.html"],
    "nist-csf": ["NIST Cybersecurity Framework", "https://www.nist.gov/cyberframework"],
    "healthit": ["HealthIT.gov (ONC)", "https://www.healthit.gov/"],
    "osha-elec": ["OSHA Electrical Safety", "https://www.osha.gov/electrical"],
    "cdc-precautions": ["CDC: Standard Precautions for All Patient Care", "https://www.cdc.gov/infection-control/hcp/standard-precautions/index.html"],
    "cms-cops": ["CMS Conditions of Participation", "https://www.cms.gov/medicare/health-safety-standards/conditions-participation-requirements"],
    "fda-advice": ["FDA Device Advice: Comprehensive Regulatory Assistance", "https://www.fda.gov/medical-devices/device-advice-comprehensive-regulatory-assistance"],
    "fda-safety": ["FDA Medical Device Safety", "https://www.fda.gov/medical-devices/medical-device-safety"],
    "fda-infusion": ["FDA: Infusion Pumps", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/infusion-pumps"],
    "fda-defib": ["FDA: External Defibrillators and AEDs", "https://www.fda.gov/medical-devices/cardiovascular-devices/external-defibrillators-aeds-and-public-access-defibrillation"],
    "fda-pulseox": ["FDA: Pulse Oximeters", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/pulse-oximeters"],
    "fda-vent": ["FDA: Ventilators and Accessories", "https://www.fda.gov/medical-devices/products-and-medical-procedures/ventilators"],
    "fda-ultrasound": ["FDA: Ultrasound Imaging", "https://www.fda.gov/radiation-emitting-products/medical-imaging/ultrasound-imaging"],
    "fda-digital": ["FDA Digital Health Center of Excellence", "https://www.fda.gov/medical-devices/digital-health-center-excellence"],
    "nfpa-99": ["NFPA 99, Health Care Facilities Code (cited, not pasted)", "https://www.nfpa.org/codes-and-standards/nfpa-99-standard-for-health-care-facilities"],
    "iec-60601": ["IEC 60601-1 (FDA recognized consensus standard page; cited, not pasted)", "https://www.fda.gov/medical-devices/standards-and-conformity-assessment-program/recognized-consensus-standards-recognized-consensus-standards"],
    "aami-cbet": ["AAMI: Certified Biomedical Equipment Technician (CBET) exam content outline", "https://aami.org/certifications/cbet/"],
  },
  cards: [
    { id: "cb001", ages: 'both', topic: "anatomy", s: "The primary job of the heart is to:", c: ["Filter waste from blood in the kidneys", "Pump blood through the circulatory system", "Exchange gases between air and blood", "Store bile from the liver in the gallbladder"], f: "The heart is a muscular pump that moves blood through the pulmonary and systemic circulations. Gas exchange occurs in the lungs, and the kidneys filter blood.", src: "openstax-ap" },
    { id: "cb002", ages: 'both', topic: "anatomy", s: "Gas exchange between air and blood occurs mainly in the:", c: ["chambers of the heart", "alveoli of the lungs", "lining of the stomach", "surface of the skin"], f: "Oxygen and carbon dioxide cross the alveolar-capillary membrane in the alveoli of the lungs. The left ventricle pumps oxygenated blood but does not perform that gas exchange.", src: "openstax-ap" },
    { id: "cb003", ages: 'both', topic: "anatomy", s: "The brain is part of which system?", c: ["The digestive system", "The nervous system", "The urinary system", "The integumentary system"], f: "The brain, spinal cord, and nerves make up the nervous system, which coordinates sensation, control, and many automatic functions.", src: "openstax-ap" },
    { id: "cb004", ages: 'both', topic: "anatomy", s: "Skin is the major organ of which system?", c: ["The respiratory system", "The integumentary system", "The skeletal system", "The endocrine system"], f: "Skin, hair, and associated glands form the integumentary system, a barrier that also helps with sensation and temperature control.", src: "openstax-ap" },
    { id: "cb005", ages: 'both', topic: "anatomy", s: "In medical terms, 'hypo-' as a prefix usually means:", c: ["Above or higher than normal, as in hypertension", "Below or lower than normal, as in hypotension", "Around or surrounding a structure, as in periosteum", "Against or opposed to a structure, as in contraindication"], f: "Hypo- means below or lower than normal, as in hypotension or hypoglycemia. Hyper- means above or excessive. Peri- means around. Contra- means against.", src: "openstax-ap" },
    { id: "cb006", ages: 'both', topic: "anatomy", s: "Blood returns to the right atrium of the heart mainly through the:", c: ["aorta", "vena cava", "pulmonary veins", "bile duct"], f: "Systemic venous blood enters the right atrium by the vena cava. The aorta carries blood out of the left ventricle. Pulmonary veins return blood from the lungs to the left atrium.", src: "openstax-ap" },
    { id: "cb007", ages: 'both', topic: "anatomy", s: "The musculoskeletal system includes:", c: ["Lungs, airways, and alveoli used in ventilation and gas exchange", "Bones, joints, and muscles used in support, protection, and movement", "Liver, pancreas, and intestine used in digestion and absorption", "Eyes, ears, and receptors used in hearing and vision"], f: "Bones, joints, cartilage, and muscles work together for support, protection, and movement. Lungs belong to the respiratory system.", src: "openstax-ap" },
    { id: "cb008", ages: 'both', topic: "electricity", s: "A 12 V source drives 0.010 A through a resistor. What is the resistance? Use Ohm's law \\(V=IR\\).", c: ["0.12 ohm", "1,200 ohm", "12 ohm", "120 ohm"], f: "Ohm's law rearranged is \\(R=V/I=12/0.010=1,200\\) ohm. Using \\(V I\\) or forgetting the decimal in the current are common mistakes.", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A simple series circuit with a voltage source and resistors." },
    { id: "cb009", ages: 'both', topic: "electricity", s: "Two resistors, \\(2.0\\,\\mathrm{k}\\Omega\\) and \\(2.0\\,\\mathrm{k}\\Omega\\), are in series with a 10 V source. What is the current?", c: ["5.0 mA", "2.5 mA", "10 mA", "2.5 A"], f: "Series resistance is \\(2.0+2.0=4.0\\,\\mathrm{k}\\Omega\\). Current is \\(I=V/R=10/4000=0.0025\\,\\mathrm{A}=2.5\\,\\mathrm{mA}\\).", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A series circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb010", ages: 'both', topic: "electricity", s: "Two \\(100\\,\\Omega\\) resistors are in parallel on a 10 V source. What is the total current from the source?", c: ["0.10 A", "0.20 A", "0.05 A", "20 A"], f: "Each branch draws \\(10/100=0.10\\,\\mathrm{A}\\), so the source current is \\(0.20\\,\\mathrm{A}\\). Equivalently \\(R_{\\mathrm{eq}}=50\\,\\Omega\\) and \\(I=10/50=0.20\\,\\mathrm{A}\\).", src: "openstax-up2", img: "img/cbet-parallel.svg", imgAlt: "A parallel circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb011", ages: 'both', topic: "electricity", s: "A device draws 2.0 A from a 24 V DC supply. What is the power?", c: ["12 W", "48 W", "26 W", "0.083 W"], f: "Electrical power is \\(P=VI=24(2.0)=48\\) W. Also \\(P=I^{2}R\\) or \\(V^{2}/R\\) once resistance is known.", src: "openstax-up2" },
    { id: "cb012", ages: 'both', topic: "electricity", s: "A line isolation monitor (LIM) in a healthcare isolated power system is used to:", c: ["Warn of a low supply voltage or a dropped phase on an isolated panel", "Warn of leakage or a first fault to ground on an isolated system", "Warn of a branch-circuit overload or a short on an isolated branch", "Warn of a patient-cable artifact or a loose lead on an isolated receptacle"], f: "In isolated power systems used in some critical care areas, a LIM watches for a first ground fault or excessive leakage and alarms so the fault can be found before a second fault occurs. Its job is to warn of leakage or a first fault to ground on an isolated system, not to replace grounding, take a voltage reading, or record a waveform.", src: "openstax-up2" },
    { id: "cb013", ages: 'both', topic: "electricity", s: "An uninterruptible power supply (UPS) is used mainly to:", c: ["Raise a low utility voltage until a transformer takes over", "Bridge a short utility outage until another source takes over", "Charge an implanted battery until a charger takes over", "Filter a sterilizer water line until a pump takes over"], f: "A UPS is used to bridge a short utility outage until another source takes over, and often to provide clean power. It is not a step-up transformer, an implant charger, or a water filter.", src: "openstax-up2" },
    { id: "cb014", ages: 'both', topic: "healthit", s: "HIPAA rules for protected health information require that workforce members:", c: ["Use PHI freely for team training, vendor demos, or unit tours", "Use PHI only as needed for treatment, payment, or operations", "Use PHI from a personal phone when the official chart is late", "Use PHI under a shared login so a coworker can finish a late chart"], f: "The HIPAA Privacy Rule limits uses and disclosures of PHI and includes a minimum-necessary standard for many uses. Workforce members should use PHI only as needed for treatment, payment, or operations, or another permitted purpose. Staff training, a personal phone, or a shared login is not a substitute for that limit.", src: "hhs-hipaa", also: ["nist-csf"] },
    { id: "cb015", ages: 'both', topic: "healthit", s: "A unique hardware address burned into a network interface is called a:", c: ["subnet mask", "MAC address", "default gateway", "wireless SSID"], f: "A MAC address identifies a network interface at the link layer. An IP address is a logical network-layer identifier and can change. A gateway is a router address; an SSID names a wireless network.", src: "healthit", also: ["nist-csf"] },
    { id: "cb016", ages: 'both', topic: "healthit", s: "IPv4 address 192.168.1.20 is commonly used as:", c: ["A public address that is freely routable on the public Internet", "A private address that is not routable on the public Internet", "A hardware address that is burned into a network interface", "A resolver address that is published for a public DNS service"], f: "RFC 1918 private address space is not routable on the public WAN. Provider routers do not forward those ranges as global destinations.", src: "healthit", also: ["nist-csf"] },
    { id: "cb017", ages: 'both', topic: "healthit", s: "The PING utility is used mainly to:", c: ["Test whether a defibrillator is calibrated and measure charge time", "Test whether a host is reachable and measure round-trip time on the path", "Test whether an operating system is patched and measure boot time", "Test whether a device is within leakage limits and measure earth current"], f: "PING sends ICMP echo requests and reports whether replies return, so you can test whether a host is reachable and measure round-trip time on the path. It is a basic network diagnostic, not a clinical calibration, patching, or leakage-current tool.", src: "healthit", also: ["nist-csf"] },
    { id: "cb018", ages: 'both', topic: "healthit", s: "A medical device that cannot talk to the electronic medical record, even though the network is up, may have a problem with:", c: ["The access point or guest portal that maps visitor traffic onto the network", "The interface or middleware that maps device data to the hospital EMR", "The display or brightness control that maps waveform contrast onto the screen", "The power strip or power brick that maps utility power onto a printer"], f: "Device-to-EMR integration often uses a gateway or middleware, commonly with a standard such as HL7. A mapping, license, or interface-engine fault can block data even when the LAN is healthy, because the interface or middleware that maps device data to the hospital EMR is the failing step.", src: "healthit", also: ["nist-csf"] },
    { id: "cb019", ages: 'both', topic: "healthit", s: "NIST cybersecurity guidance for systems that handle sensitive data emphasizes:", c: ["Confidentiality, Integrity, Availability, Authentication, Authorization, Accounting", "Govern, Identify, Protect, Detect, Respond, Recover as the six framework functions", "Inventory, Encryption, Backups, Firewalls, Patching, Training", "Privacy, Consent, Retention, Disposal, Billing, Marketing"], f: "NIST Cybersecurity Framework 2.0 organizes work into six functions: Govern, Identify, Protect, Detect, Respond, Recover as the six framework functions. Patching, access control, and monitoring support those functions.", src: "nist-csf" },
    { id: "cb020", ages: 'both', topic: "healthit", s: "A workstation will not boot and the display stays dark, even on a known-good monitor. A useful early hardware check is:", c: ["The operating-system image, recovery disk, and boot files", "The power supply, cabling, and POST status", "The video-driver package, cache, and display settings", "The CMOS boot order, clock, and drive map"], f: "A dead workstation is often a local power, cable, memory, or motherboard problem. Confirm the power supply, cabling, and POST status before blaming an enterprise image, a video driver, or the CMOS menu.", src: "healthit", also: ["nist-csf"] },
    { id: "cb021", ages: 'both', topic: "healthit", s: "Applying OS and application patches on networked medical systems is important because:", c: ["Unpowered systems are a common path for downtime and lost work", "Unpatched systems are a frequent path for malware and data breaches", "Unvalidated patches are a typical path for outages and device faults", "Unencrypted backups are a frequent path for theft and data exposure"], f: "Timely, tested patching reduces known vulnerabilities. Unpatched systems are a frequent path for malware and data breaches. Clinical systems still need a change process so a patch does not break a device or workflow.", src: "healthit", also: ["nist-csf"] },
    { id: "cb022", ages: 'both', topic: "healthit", s: "A wireless access point is used to:", c: ["Connect two IP subnets to the routed network", "Connect Wi-Fi clients to the wired network", "Connect a 120 V supply to the logic circuits", "Connect public addresses to the wireless clients"], f: "An access point is used to connect Wi-Fi clients to the wired network, and sometimes to bridge other APs to the LAN. It is not a default gateway, a power transformer, or a DHCP service for public addresses.", src: "healthit", also: ["nist-csf"] },
    { id: "cb023", ages: 'both', topic: "healthit", s: "A switch, as opposed to a simple hub, typically:", c: ["Forward each frame to every port by design", "Forward each frame to the correct port by MAC address", "Forward each packet to another subnet by IP address", "Forward each call to a PBX trunk by extension number"], f: "A switch forwards frames toward the correct port by MAC address. A hub floods every frame. Inter-subnet routing is the job of a router or layer-3 device, and analog trunks belong to a PBX.", src: "healthit", also: ["nist-csf"] },
    { id: "cb024", ages: 'both', topic: "healthit", s: "A default gateway is:", c: ["The MAC address a station uses to reach a local printer", "The router address a host uses to reach other networks", "The SSID a client uses to reach a guest network", "The username a user uses to reach the EMR"], f: "If a destination is not on the local subnet, the host sends packets to its default gateway, which then routes them onward. A default gateway is the router address a host uses to reach other networks.", src: "healthit", also: ["nist-csf"] },
    { id: "cb025", ages: 'both', topic: "healthit", s: "Hardening a Windows PC used near a medical device should include:", c: ["Shared passwords, open sessions, unlocked screens, and stale updates", "Unique accounts, required sign-in, auto-lock, and timely security updates", "Shared accounts, skipped the sign-in, unlocked screens, and stale updates", "Administrator rights, skipped sign-in, unlocked screens, and stale updates"], f: "Unique credentials, sign-in, auto-lock, patching, and least privilege reduce the chance that one compromised session exposes PHI or device control. A basic hardening set is unique accounts, required sign-in, auto-lock, and timely security updates. Shared posted passwords are a common audit finding.", src: "healthit", also: ["nist-csf"] },
    { id: "cb026", ages: 'both', topic: "healthit", s: "A virtual server is:", c: ["A physical server running on dedicated hardware", "A guest operating system running on a hypervisor", "A container image running as a process on the host kernel", "A firmware module running on a medical device"], f: "Virtualization lets multiple servers share one host. A virtual machine is a guest operating system running on a hypervisor, sharing physical hardware. Medical device vendors may or may not allow a virtualized server, so the vendor statement matters.", src: "healthit", also: ["nist-csf"] },
    { id: "cb027", ages: 'both', topic: "healthit", s: "Cloud computing for a clinic means, at a basic level:", c: ["Using computing resources only on site under a service plan", "Using computing resources over a network, often off site, under a service model", "Using computing resources when HIPAA duties end under a service contract", "Using computing resources only for autoclave control under a service offering"], f: "Cloud computing means using computing resources over a network, often off site, under a service model. HIPAA still applies: a business associate agreement and security controls are needed when PHI is involved. It is not a way to drop those duties, and it is not a sterilizer control method.", src: "healthit", also: ["nist-csf"] },
    { id: "cb028", ages: 'both', topic: "healthit", s: "A cable tester or toner is most useful when you need to:", c: ["Verify a blood-pressure cuff and its calibration", "Verify a copper network run and its pairs and continuity", "Verify a pulse-oximeter probe and its simulator", "Verify a defibrillator cable and its pads"], f: "Testers and toners help prove a cable's identity, continuity, and sometimes pair mapping or length. They are used to identify or verify a copper network run and its pairs and continuity. They do not replace clinical calibration tools.", src: "healthit", also: ["nist-csf"] },
    { id: "cb029", ages: 'both', topic: "healthit", s: "HHS has published cybersecurity performance goals for healthcare because:", c: ["Attacks on hospitals are rare and rarely expose PHI", "Attacks on hospitals can disrupt care and expose PHI", "Attacks on hospitals matter only for retail stores and similar shops", "Attacks on hospitals do not require technical or administrative safeguards"], f: "Healthcare is a frequent ransomware and breach target. Attacks on hospitals can disrupt care and expose PHI. Federal performance goals and HIPAA security requirements aim to keep systems and PHI safer so care can continue.", src: "healthit", also: ["nist-csf"] },
    { id: "cb030", ages: 'both', topic: "healthit", s: "A KVM switch is used to:", c: ["Share a lab analyzer, centrifuge, and rack among benches", "Share a keyboard, video, and mouse among computers", "Share an isolated-power transformer, outlet, and bus among rooms", "Share a gas blender, mixer, and line among cases"], f: "KVM hardware or software is used to share a keyboard, video, and mouse among computers. It is not a lab analyzer or an isolated-power device.", src: "healthit", also: ["nist-csf"] },
    { id: "cb031", ages: 'both', topic: "function", s: "Korotkoff sounds are used when measuring:", c: ["Body temperature with a probe and thermometer", "Blood pressure with a cuff and stethoscope or simulator", "End-tidal carbon dioxide with a capnograph and sampling line", "Electrical leakage with a safety analyzer and test lead"], f: "Korotkoff sounds are the auscultatory cues used when measuring blood pressure with a cuff and stethoscope or simulator. They are not a temperature, capnography, or leakage-current measurement.", src: "fda-advice" },
    { id: "cb032", ages: 'both', topic: "function", s: "Einthoven's triangle refers to:", c: ["The three standard leveling points of an operating table or stand", "The three standard limb leads of the ECG, leads I, II, and III", "The three standard zones of a radiation sign or door", "The three standard cells of a device battery or pack"], f: "Einthoven's triangle is formed by leads I, II, and III on the right arm, left arm, and left leg. Einthoven's triangle is formed by the three standard limb leads of the ECG, leads I, II, and III. It is a basic ECG lead model, not a table or safety-sign topic.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform showing P, QRS, and T waves." },
    { id: "cb033", ages: 'both', topic: "function", s: "On a normal ECG, the QRS complex mainly represents:", c: ["Atrial depolarization", "Ventricular depolarization", "Ventricular repolarization", "Atrial repolarization"], f: "The QRS complex mainly reflects ventricular depolarization. The P wave is atrial depolarization, and the T wave is ventricular repolarization.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG waveform with the P wave, QRS complex, and T wave labeled.", imgAsk: true },
    { id: "cb034", ages: 'both', topic: "function", s: "A defibrillator analyzer is used to:", c: ["Deliver a defibrillator's output energy during a treatment", "Measure a defibrillator's output energy during a test", "Capture a defibrillator's ECG signal during a treatment", "Pace a defibrillator's output pulse during a test"], f: "A defibrillator analyzer is test equipment. It is used to measure a defibrillator's output energy during a test, along with other scheduled functions. It is not a therapy device and should not be used to treat a patient.", src: "fda-defib" },
    { id: "cb035", ages: 'both', topic: "function", s: "An electrical safety analyzer is used to:", c: ["Measure ECG amplitude, SpO2, and similar monitor points", "Measure leakage current, ground resistance, and similar safety points", "Measure defibrillator energy, pacing current, and similar therapy points", "Measure label stock, wristband length, and similar supply points"], f: "Safety analyzers measure leakage current, ground resistance, and similar safety points against the limits in the applicable standard, for example IEC 60601 or a facility policy based on NFPA 99. They are not clinical monitors.", src: "fda-safety" },
    { id: "cb036", ages: 'both', topic: "function", s: "A physiologic simulator is used to:", c: ["Provide a known defibrillator shock or charge to a test load", "Provide a known ECG, pressure, or SpO2 signal to a monitor", "Provide isolated power or backup to surgical-suite outlets", "Provide image storage or reports to a radiology archive system"], f: "Simulators let you test a monitor or module with a known waveform or value so you can tell a device fault from a cable or electrode problem. A physiologic simulator is used to provide a known ECG, pressure, or SpO2 signal to a monitor.", src: "fda-advice" },
    { id: "cb037", ages: 'both', topic: "function", s: "Blood pressure in the clinic is commonly reported in:", c: ["Lumens, a lighting output unit", "Millimeters of mercury (mmHg)", "Becquerel, a radioactivity unit", "Siemens, a conductance unit"], f: "Arterial blood pressure is measured in millimeters of mercury (mmHg). Lumens measure light, becquerel is activity, and siemens is conductance.", src: "fda-advice" },
    { id: "cb038", ages: 'both', topic: "function", s: "A pulse oximeter estimates:", c: ["Carbon dioxide in exhaled gas from infrared absorption in a breathing-circuit adapter", "Oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed", "Core temperature in a body cavity from a thermistor in a bladder or esophageal probe", "Blood pressure in an artery from oscillometric pulses in an arm cuff and pump"], f: "Pulse oximetry estimates oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed, using at least two light wavelengths. EtCO2 is a capnography measurement, not the same sensor.", src: "fda-pulseox" },
    { id: "cb039", ages: 'both', topic: "function", s: "End-tidal CO2 (EtCO2) monitoring is used mainly to:", c: ["Follow oxygen saturation in arterial blood during sedation or ventilation", "Follow carbon dioxide in exhaled gas during sedation or ventilation", "Follow a 12-lead ECG waveform during an outpatient visit", "Follow invasive blood pressure during an operative case"], f: "Capnography is used to follow carbon dioxide in exhaled gas during sedation or ventilation, and is a key check of ventilation and airway integrity. It complements, rather than always replaces, oximetry.", src: "fda-advice" },
    { id: "cb040", ages: 'both', topic: "function", s: "A telemetry system in a hospital is used to:", c: ["Send isolated power from a transformer to a surgical-suite receptacle", "Send physiologic waveforms from a mobile patient to a central station", "Send steam from an autoclave to a sterile-processing instrument load", "Send suction from a headwall regulator to a collection canister"], f: "Telemetry uses radios or a network to carry ECG and related signals so a patient can move while being watched at a central station. Telemetry is used to send physiologic waveforms from a mobile patient to a central station.", src: "fda-digital" },
    { id: "cb041", ages: 'both', topic: "function", s: "An infusion pump (LVP or syringe) is designed to:", c: ["Deliver warmed fluids or blankets at a set temperature and hold", "Deliver fluids or medications at a set rate and volume", "Deliver urine-output values or volumes at a set interval and count", "Deliver anesthetic gases or vapors at a set mixture and ratio"], f: "Infusion devices control rate and volume. Different types (large-volume, syringe, PCA, and injectors) fit different therapies, but the basic job is to deliver fluids or medications at a set rate and volume.", src: "fda-infusion" },
    { id: "cb042", ages: 'both', topic: "function", s: "A PCA pump is intended to:", c: ["Let a patient start extra ventilator breaths within programmed limits", "Let a patient request extra pain doses within programmed limits", "Let a patient capture extra ECG leads within programmed limits", "Let a patient raise extra table heat within programmed limits"], f: "Patient-controlled analgesia pumps give a programmed basal and/or demand dose with lockout limits. A PCA pump can let a patient request extra pain doses within programmed limits. They are not ventilators or ECG machines.", src: "fda-infusion" },
    { id: "cb043", ages: 'both', topic: "function", s: "A ventilator is life-support equipment whose basic job is to:", c: ["Move blood through the arteries of a patient", "Move air through the lungs of the patient during ventilation", "Move ECG signals through the chest leads on a patient", "Move heat through the warming blankets around a patient"], f: "Ventilators deliver a set gas pattern so they can move air through the lungs of the patient during ventilation, when breathing needs help or replacement. They require trained use, alarms, and backup power. They are not simple monitors, and they do not move blood, ECG signals, or blanket heat.", src: "fda-vent" },
    { id: "cb044", ages: 'both', topic: "function", s: "An external defibrillator is used to:", c: ["Deliver a pacing pulse for a slow heart rate", "Deliver a shock for a dangerous heart rhythm", "Deliver a light signal for an oxygen-saturation value", "Deliver suction for a headwall canister"], f: "Defibrillators treat shockable arrhythmias under clinical protocols. An external defibrillator is used to deliver a shock for a dangerous heart rhythm. An implanted pacemaker is a different device. External transcutaneous pacing is a related but separate function on some units.", src: "fda-defib" },
    { id: "cb045", ages: 'both', topic: "function", s: "An electrosurgical unit (ESU) is used in the operating room to:", c: ["Close tissue with a staple line, clip, or suture", "Cut or coagulate tissue with a high-frequency current", "Clear fluid from tissue with a suction canister", "Rinse tissue with sterile saline or sterile water"], f: "ESUs deliver RF current through an active electrode, with a return path (monopolar) or between the tips (bipolar), to cut or coagulate tissue. Safe use depends on return-electrode integrity, accessories, and smoke control.", src: "fda-advice" },
    { id: "cb046", ages: 'both', topic: "safety", s: "Patient leakage current, as used in electrical safety testing of medical equipment, is:", c: ["Current in the protective earth conductor during a fault test", "Current in an applied part connected to the patient circuit", "Current in the earth-leakage meter during a setup check", "Current in the supply cord drawn from the wall outlet"], f: "Patient leakage is current in an applied part connected to the patient circuit. Earth leakage is current in the protective-earth conductor. IEC 60601-1 and NFPA 99 treat these as different tests with different limits. Use the method and limits in the edition that applies to that device.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb047", ages: 'both', topic: "function", s: "A steam sterilizer (autoclave) uses which combination as its basic killing method?", c: ["Dry air over a documented interval and temperature", "Saturated steam under pressure at a documented time and temperature", "Ultraviolet light through a documented exposure and temperature", "A paper wrap under a documented hold and temperature"], f: "Steam sterilizers use saturated steam under pressure at a documented time and temperature, often with a recorded load process. Dry air, a night-light, or a paper wrap alone is not a sterilization cycle.", src: "fda-advice" },
    { id: "cb048", ages: 'both', topic: "function", s: "A laboratory centrifuge is used to:", c: ["Separate components from a sample with circulating dry air", "Separate components of a sample by spinning the tube at speed", "Separate components in a sample with ultraviolet light", "Separate components around a sample by wrapping the tube"], f: "Centrifuges spin samples so denser components move outward. They separate components of a sample by spinning the tube at speed. Imbalance, lid interlocks, and speed verification are typical safety and performance points.", src: "fda-advice" },
    { id: "cb049", ages: 'both', topic: "function", s: "A laboratory refrigerator or freezer is important because:", c: ["It keeps emergency-cart batteries and packs at the required charging temperature", "It keeps reagents and samples at the required storage temperature and alarm limits", "It keeps steel surgical instruments and trays at the required sterilizing temperature", "It keeps isolated-power transformers and breakers at the required output temperature"], f: "Lab cold storage is important because it keeps reagents and samples at the required storage temperature and alarm limits, often with monitoring. Freezing is not a sterilizer for surgical tools, and a refrigerator is not a power system or a battery charger.", src: "fda-advice" },
    { id: "cb050", ages: 'both', topic: "function", s: "An ultrasound imager forms pictures mainly by:", c: ["Sending a static magnetic field and radiofrequency pulses", "Sending high-frequency sound and receiving echoes", "Sending a nuclear tracer and detecting gamma rays", "Sending infrared light and sensing skin temperature"], f: "Diagnostic ultrasound transmits pulses and listens for reflections, sending high-frequency sound and receiving echoes. MRI uses magnetic fields and radiofrequency; nuclear medicine uses radioactive tracers; thermal cameras read skin temperature.", src: "fda-ultrasound" },
    { id: "cb051", ages: 'both', topic: "function", s: "A digital multimeter (DVM) in a shop is used to:", c: ["Measure a patient's temperature or skin value on the circuit under test", "Measure voltage, current, or resistance in a circuit under test", "Measure pacing pulses or intervals across a circuit under test", "Measure wristband stock or labels for a circuit under test"], f: "A DVM is general test equipment. A DVM is used to measure voltage, current, or resistance in a circuit under test. Use it on de-energized circuits where required, with the right function and range, and never as a substitute for a medical-grade safety analyzer when that test is needed.", src: "fda-advice" },
    { id: "cb052", ages: 'both', topic: "function", s: "An SCD (sequential compression device) is used to:", c: ["Deliver shocks to the chest in a sequence to help restart a stopped heart", "Inflate garments on a limb in a cycle to help reduce stasis in the legs", "Provide breaths to the airway in a pattern to help replace failed breathing", "Measure carbon dioxide on a circuit in a series to help follow exhaled gas"], f: "SCDs inflate garments on a limb in a cycle to help reduce stasis, applying intermittent pneumatic compression, often to the legs. They are not life-support ventilators or defibrillators.", src: "fda-advice" },
    { id: "cb053", ages: 'both', topic: "function", s: "A patient warmer or thermal blanket system is used to:", c: ["Capture a routine ECG waveform for the patient", "Manage body temperature for the patient", "Measure urine volume for the patient", "Provide wall suction for the patient"], f: "Temperature-management devices manage body temperature for the patient by heating or, in some systems, also cooling under a protocol. Over- or under-heating is a risk, so probes, alarms, and accessories matter.", src: "fda-advice" },
    { id: "cb054", ages: 'both', topic: "function", s: "A wall suction regulator is used to:", c: ["Raise oxygen concentration in a breathing gas from a wall blender", "Control vacuum applied to a suction circuit from a wall source", "Deliver pacing pulses to a patient lead from a wall outlet", "Measure blood pressure on an arm cuff from a wall port"], f: "Suction regulators set and limit vacuum from a wall or portable source. A suction regulator is used to control vacuum applied to a suction circuit from a wall source. They are not oxygen blenders or pacing devices.", src: "fda-advice" },
    { id: "cb055", ages: 'both', topic: "function", s: "A fetal monitor typically tracks:", c: ["An adult 12-lead ECG and rhythm strip on a ward monitor", "Fetal heart rate and uterine activity on a labor monitor", "Laboratory centrifuge speed and imbalance on a lab display", "Steam-chamber pressure and jacket temperature on an autoclave display"], f: "Fetal monitors record FHR and contractions (TOCO on the abdomen, or intrauterine pressure when indicated) so clinicians can assess well-being in labor or testing. A fetal monitor typically tracks fetal heart rate and uterine activity on a labor monitor.", src: "fda-advice" },
    { id: "cb056", ages: 'both', topic: "function", s: "An anesthesia machine, at a basic level, is used to:", c: ["Deliver a wash cycle of water and detergent, and sterilize the instruments", "Deliver a mix of gases and anesthetic, and ventilate the patient", "Deliver a copy of notes and reports, and archive the case packet", "Deliver a measurement of weight and length, and document the newborn"], f: "Anesthesia workstations blend gases, vaporize agent, and ventilate, with many safety interlocks and scavengers. An anesthesia workstation is used to deliver a mix of gases and anesthetic, and ventilate the patient. They are life-support systems and are not sterilizers.", src: "fda-advice" },
    { id: "cb057", ages: 'both', topic: "function", s: "An external pacemaker (for example a transcutaneous or temporary external unit) is used to:", c: ["Measure oxygen saturation with a probe when that value is indicated", "Deliver temporary pacing pulses with a lead when that strategy is indicated", "Measure end-tidal carbon dioxide with a line when that value is indicated", "Warm IV fluids or blood with a plate when that therapy is indicated"], f: "External or temporary pacemakers deliver temporary pacing pulses with a lead when that strategy is indicated under a clinical protocol. They are not oximeters or fluid warmers. Implantable pacemakers are a different class of device.", src: "fda-advice" },
    { id: "cb058", ages: 'both', topic: "function", s: "A fluid warmer is used in perioperative or emergency care to:", c: ["Deliver a defibrillation shock or pacing shock to a patient during resuscitation", "Warm fluids or blood products for a patient during infusion or transfusion", "Capture EEG waveforms or sleep stages from a patient during a clinic visit", "Replace a station UPS or battery for a patient during a power outage"], f: "Fluid warmers reduce the chance of hypothermia from cold infusions. A fluid warmer is used to warm fluids or blood products for a patient during infusion or transfusion. They must be used with the right disposables and temperature limits. They are not defibrillators.", src: "fda-advice" },
    { id: "cb059", ages: 'both', topic: "function", s: "A spirometer is a diagnostic device used to:", c: ["Measure how much energy, and how quickly a defibrillator charges a test load", "Measure how much air, and how fast a person moves that air in a breathing test", "Measure how much fluid, and how rapidly a dialyzer removes blood water", "Measure how much glucose, and how soon a meter reads a test strip"], f: "Spirometry records volumes and flow for pulmonary testing, measuring how much air, and how fast a person moves that air in a breathing test. Calibration with a syringe and infection-control practices are typical technical points.", src: "fda-advice" },
    { id: "cb060", ages: 'both', topic: "function", s: "An otoscope is used to:", c: ["Look at the retina of the eye with a lighted diagnostic scope", "Look into the ear canal and at the eardrum with a lighted instrument", "Look at a blood-pressure cuff and bulb with a lighted handle", "Look into the airway opening and teeth with a lighted blade"], f: "An otoscope is used to look into the ear canal and at the eardrum with a lighted instrument, plus magnification. An ophthalmoscope is the related tool for the eye.", src: "fda-advice" },
    { id: "cb061", ages: 'both', topic: "troubleshooting", s: "A monitor is completely dark, and no power light is on. The wall outlet is live. A sound first check is:", c: ["The SpO2 probe, cable, and sensor or module, then the display", "The power cord, switch, and inlet fuse or breaker, then the supply", "The network cable, jack, and interface or port, then the EMR path", "The ECG leads, trunk, and trunk cable or jack, then the amplifier"], f: "No lights often means no power reaching the device. Check the obvious path (cord, switch, fuse or breaker, then the supply) before swapping major boards or blaming the network. A sound first check is the power cord, switch, and inlet fuse or breaker, then the supply.", src: "fda-digital" },
    { id: "cb062", ages: 'both', topic: "troubleshooting", s: "A physiologic monitor shows a flat ECG and a 'leads off' message, but a simulator on the same cable is normal. The more likely problem is:", c: ["The display backlight, cable, or bezel on the monitor", "The electrodes, skin prep, or lead wires on the patient", "The emergency generator, bus, or transfer switch on the campus", "The steam supply, valve, or boiler loop on the sterilizer"], f: "If a known-good simulator works, the input and cable path are probably fine. The next place to look is the connection to the patient: the electrodes, skin prep, or lead wires on the patient.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform used as a known test pattern." },
    { id: "cb063", ages: 'both', topic: "troubleshooting", s: "Two work orders arrive: a ventilator in use on a patient has a critical alarm, and a scale in a clinic is slightly out of date for its check. Which should you handle first?", c: ["The clinic scale first, because its inspection interval has already expired or lapsed", "The in-use ventilator first, because of risk, urgency, and effect on care and safety", "The clinic scale first, because that work order was entered earlier or stamped first", "The in-use ventilator first, because it is the newer or older of the two devices"], f: "Prioritize by risk, urgency, and effect on care. The in-use ventilator comes first because of risk, urgency, and effect on care and safety, ahead of a noncritical clinic scale.", src: "fda-vent" },
    { id: "cb064", ages: 'both', topic: "troubleshooting", s: "A nurse reports 'the infusion pump is broken' after a dose was entered incorrectly and the pump alarmed as designed. This is best classified as:", c: ["A complete device failure, if you confirm that pump will not run", "A use-related issue, after you confirm the pump behaves as designed", "A network-interface fault, when you confirm this pump cannot send results", "A power-supply fault, if you confirm the unit will not power on"], f: "If the device alarms and behaves as designed when a wrong entry is made, the event may be a use error. If the pump is working as designed, treat the event as a use-related issue, after you confirm the pump behaves as designed. Still verify the pump, then help with training or a workflow change. Do not skip the technical check.", src: "fda-infusion" },
    { id: "cb065", ages: 'both', topic: "troubleshooting", s: "One telemetry transmitter on a hall drops out, but the whole unit's other transmitters are fine. You should first suspect:", c: ["A campus-wide network fault affecting every clinical unit or floor", "A local transmitter fault affecting that battery, antenna, or dead zone", "A facility-wide display fault affecting every central station or printer", "A nurse-call lighting fault affecting a dome on another unit or wing"], f: "A single-device problem is more often a local transmitter fault affecting that battery, antenna, or dead zone than a system-wide failure. Compare with nearby working devices.", src: "fda-digital" },
    { id: "cb066", ages: 'both', topic: "troubleshooting", s: "Every telemetry display on a unit fails at once, while other hospital networks still work. That pattern suggests:", c: ["A single-bed problem, such as one electrode pack, one transmitter, or one cable", "A shared-system problem, such as an access point, a controller, or that unit's path", "A single-bay problem, such as one bed scale, one display stand, or one wall jack", "A single-room problem, such as one otoscope bulb, one lamp, or one charger"], f: "When many devices of one system fail together, look at a shared-system problem such as an access point, a controller, or that unit's path, not one accessory.", src: "fda-digital" },
    { id: "cb067", ages: 'both', topic: "troubleshooting", s: "A newly installed monitor will not send data to the EMR, but waveforms look correct at the bedside. A useful early step is:", c: ["Confirm the IV catheter and its placement or depth at the bedside", "Confirm network settings, device ID, and the interface or middleware status", "Confirm defibrillator energy and its default or limit at the bedside", "Confirm display brightness and its calibration or contrast at the bedside"], f: "Bedside operation can be fine while ADT or results never reach the record because of IP, ports, time, a certificate, or a mapping in middleware. If the bedside display is fine but the record is empty, confirm network settings, device ID, and the interface or middleware status. Check those before swapping a working display.", src: "fda-digital" },
    { id: "cb068", ages: 'both', topic: "troubleshooting", s: "A staff member needs a short in-service on a new vital-signs monitor. Your communication should be:", c: ["Cover unofficial workarounds that the team already uses on the unit during in-service", "Cover approved, safe use of the device as written in the manual during in-service", "Cover how to post a patient census on a public hallway screen during in-service", "Cover how to silence alerts that the team finds noisy during a case in-service"], f: "Technicians often train clinicians on proper use. Stay clear, in plain language, and limited to approved, safe use of the device as written in the manual during in-service, and do not invent workarounds that bypass safety.", src: "fda-advice" },
    { id: "cb069", ages: 'both', topic: "troubleshooting", s: "A defibrillator fails an energy-output test on a defibrillator analyzer, but the device powers on. The right next path is:", c: ["Return it to the crash cart, document the failed output, and post or keep the result", "Remove it from service, investigate, and repair or escalate per policy and procedure", "Schedule it for a following inspection, document the failed output, and post or keep the result", "Keep it in limited backup use, document the failed output, and post or keep the result"], f: "A failed energy test means the device must not stay in clinical service. Remove it from service, investigate, and repair or escalate per policy and procedure. Tag it, document, and follow the service procedure. Do not use people as test loads.", src: "fda-defib" },
    { id: "cb070", ages: 'both', topic: "troubleshooting", s: "An ESU repeatedly faults with a return-electrode alarm. A practical first check is:", c: ["The active electrode tip, its cable, and its placement, then the generator output", "The return pad, its cable, and its placement, then the generator return circuit", "The isolated-power transformer, its bus, and its bonding, then the suite supply", "The smoke evacuator, its hose, and its filter, then the vacuum source"], f: "Return-electrode (REM or CQM) alarms are often an accessory or application issue. Check the return pad, its cable, and its placement, then the generator return circuit if the accessories are good.", src: "fda-advice" },
    { id: "cb071", ages: 'both', topic: "troubleshooting", s: "A syringe pump stops and reports occlusion. A sound first set of checks is:", c: ["The motor, gearbox, and wiring first, then the drive if the motor is quiet", "The tubing, clamps, and position first, then the pump if the line is clear", "The wireless network, interface, and cable first, then the host if charting is late", "The power cord, fuse, and inlet first, then the display if the screen is dark"], f: "Occlusion alarms are often clamps, kinks, a closed stopcock, or a high back-pressure site. Check the tubing, clamps, and position first, then the pump if the line is clear.", src: "fda-infusion" },
    { id: "cb072", ages: 'both', topic: "troubleshooting", s: "A PCA pump can be started, but the lockout interval does not match the order. After confirming the order, you should:", c: ["Treat this as a normal start-up delay or hold and leave this pump in use until a subsequent dose", "Treat it as a programming or configuration problem and keep the pump unused until corrected", "Treat that as a battery warning or message and leave that pump in use when you cycle power", "Treat the event as a documentation gap or note and leave the unit in use when you add a journal comment"], f: "A lockout that does not match the prescribed program is a safety issue. Treat it as a programming or configuration problem and keep the pump unused until it is correct. Do not leave it in service or change therapy limits without the proper clinical and technical process.", src: "fda-infusion" },
    { id: "cb073", ages: 'both', topic: "troubleshooting", s: "A feeding pump free-flows when the door is open and no set is loaded correctly. That is:", c: ["A normal delivery mode, so do not take this pump out of clinical duty", "A serious safety fault, so take the infusion pump out of service", "A cosmetic housing issue, so do not take that pump out of clinical duty", "A test-mode behavior, so do not take the unit out of clinical duty"], f: "Free-flow of enteral or IV fluid when the set is not properly engaged is a serious hazard. Free-flow is a serious safety fault, so take the infusion pump out of service. The device should be removed from service and repaired or replaced.", src: "fda-advice" },
    { id: "cb074", ages: 'both', topic: "troubleshooting", s: "A laboratory centrifuge will not start. The lid interlock still reads open even though the lid is closed. A likely cause is:", c: ["A worn drive motor or gearbox, so the rotor never reaches the needed speed", "A lid switch, latch, or interlock fault, so the lid is never seen as closed", "A speed-program typo or misentry, so the lid is still shown as closed", "A failed brake or clutch, so a start is still allowed on a closed lid"], f: "Centrifuges should not run with the lid open. If the interlock never sees 'closed,' look at the switch, latch, and wiring before replacing a motor. A likely cause is a lid switch, latch, or interlock fault, so the lid is never seen as closed.", src: "fda-advice" },
    { id: "cb075", ages: 'both', topic: "troubleshooting", s: "A lab refrigerator used for reagents is at 12 C, above its set range, and the alarm did not call. You should:", c: ["Protect the contents, keep the box in use, and schedule the upcoming temperature check or audit", "Protect the contents, take the box out of use, and find why cooling and the alarm failed", "Protect the contents, keep the box in use, and transfer stock to a backup warmer or cabinet", "Protect the contents, keep the box in use, and wait for the alarm to clear or reset on its own"], f: "Out-of-range storage can ruin reagents or samples. Protect the contents, take the box out of use as needed, and find why cooling and the alarm both failed. Safeguard the contents, then repair the refrigeration and the alarm path. Do not silence alarms to hide the problem.", src: "fda-advice" },
    { id: "cb076", ages: 'both', topic: "troubleshooting", s: "An otoscope light is dim. The handle has fresh batteries. A simple next check is:", c: ["The zoning signs at the MRI entrance and door", "The lamp, contacts, and head connection in that handle", "The steam pressure, jacket, and trap in the sterilizer", "The database index, application, and server in the EMR"], f: "A dim otoscope is often a lamp, dirty contacts, or a poor connection in the head or handle. Power is already plausible if the batteries are good. A simple next check is the lamp, contacts, and head connection in the handle.", src: "fda-advice" },
    { id: "cb077", ages: 'both', topic: "troubleshooting", s: "A scale used for medication dosing reads 0.4 kg high on a known test weight. You should:", c: ["Keep it in clinical dosing use until the upcoming scheduled calibration or check", "Remove it from clinical dosing use until it is calibrated or replaced and documented", "Keep it in clinical dosing use when you post a 0.4 kg correction or factor", "Keep it in clinical dosing use when you add a note in the equipment journal or worksheet"], f: "A scale used for dosing must be accurate. Remove it from clinical dosing use until it is calibrated or replaced and documented. Take it out of that use, calibrate or repair it, and document. Mental corrections are not a safe standing practice.", src: "fda-advice" },
    { id: "cb078", ages: 'both', topic: "troubleshooting", s: "A stress-test ECG is noisy only when the treadmill is running. A useful direction is:", c: ["Look for a plant-boiler fault, a steam leak, or interference from the utility corridor", "Look for motion, cable routing, grounding, or interference from the treadmill drive", "Look for a shop-simulator fault, a lead break, or interference from a stored cable", "Look for a defibrillator default, an energy setting, or interference from a crash cart"], f: "Noise that appears only when a treadmill runs often means you should look for motion, cable routing, grounding, or interference from the treadmill drive. Compare with a standing ECG.", src: "fda-advice" },
    { id: "cb079", ages: 'both', topic: "troubleshooting", s: "An ultrasound unit powers on but shows no image, and a known-good probe on that connector is also dark. The fault is more likely:", c: ["In the last probe you used, rather than the port, card, or software", "In the imaging system, rather than just the last probe you used", "In the facility boiler, rather than the port, card, or software", "In a nearby tourniquet, rather than the port, card, or software"], f: "If a known-good probe also fails on that port, the fault is in the imaging system, rather than just the last probe you used. If only one probe fails on a known-good port, look at that probe.", src: "fda-ultrasound" },
    { id: "cb080", ages: 'both', topic: "troubleshooting", s: "A pulse-oximeter reading is blank on a patient with cold fingers, but a simulator at the same cable reads 98%. This suggests:", c: ["A failed simulator instead of a proved cable or probe problem", "A poor peripheral signal, not a proved monitor failure", "A failed alarm setting instead of a proved sensor or cable problem", "A nearby steam leak instead of a proved monitor or cable problem"], f: "A simulator isolates the device and cable. A good simulator reading with a bad patient waveform points to a poor peripheral signal, not a proved monitor failure. A good simulator result with a poor patient signal points to perfusion, placement, or ambient light, which clinicians may address. Still treat alarms seriously.", src: "fda-pulseox" },
    { id: "cb081", ages: 'both', topic: "troubleshooting", s: "A ventilator in the shop fails a volume check on a test lung, outside its allowed error. You should:", c: ["Return it to service when you see that the display still looks normal or unchanged", "Keep it out of service until it is repaired or escalated, then corrected and verified", "Return it to service when you widen the allowed error or tolerance on the inspection tag", "Return it to service when you mark the test-lung check as complete or passed"], f: "Life-support equipment that fails a performance test stays out of service until it is corrected and verified. Keep it out of service until it is repaired or escalated, then corrected and verified. Do not pass it by changing limits without authority.", src: "fda-vent" },
    { id: "cb082", ages: 'both', topic: "troubleshooting", s: "A balloon pump (IABP) in use has a gas-loss alarm. Your first priority is:", c: ["Finish a planned inventory check in the shop, then follow the device procedure from the shop", "Stay with the clinical team at the bedside, then follow the emergency procedure for the device", "Open the drive-gas circuit in the shop first, then follow the emergency procedure from the shop", "Reset the preventive-maintenance interval in the CMMS, then follow the device procedure from the shop"], f: "An IABP is life-support. A leak or gas-loss alarm is urgent. Stay with the clinical team at the bedside, then follow the emergency procedure for the device; do not treat it as a routine shop call while it is on a patient.", src: "fda-advice" },
    { id: "cb083", ages: 'both', topic: "troubleshooting", s: "An anesthesia machine fails a pre-use leak test. The correct action is:", c: ["Use it for the case when you save the failed leak test or finding in the journal", "Leave it out of use for a case until the leak is found and the check passes", "Use it for the case when you review that the last case on that machine went well or seemed normal", "Use it for the case when you schedule a full leak test or inspection for a following shift"], f: "Pre-use checks exist to catch leaks and other faults before a patient is anesthetized. Leave it out of use for a case until the leak is found and the check passes, after the machine is repaired.", src: "fda-advice" },
    { id: "cb084", ages: 'both', topic: "troubleshooting", s: "A surgical table will not unlock to reposition, and the patient is on the table. You should:", c: ["Keep the patient in place first, wait for a following scheduled case, and delay an emergency release", "Keep the patient safe first, use an emergency unlock if one exists, and avoid forcing unknown parts", "Keep the patient in place first, transfer to another table immediately, and skip an emergency release", "Keep the patient in place first, cancel the case from the hallway, and delay telling the clinical team"], f: "With a patient on the table, safety and an approved emergency release come first. Keep the patient safe first, use an emergency-unlock method if there is one, and avoid forcing unknown parts. Do not improvise with force that could injure the patient or wreck the table.", src: "fda-advice" },
    { id: "cb085", ages: 'both', topic: "troubleshooting", s: "An infant warmer's skin-temperature probe is off the skin, and the unit is in servo mode. The unsafe pattern to watch for is:", c: ["The heater output can fall to a minimum because the skin probe is detached", "The heater can overshoot because it no longer sees a true skin temperature", "The unit can switch to a manual set-point and hold heat unchanged on the skin", "The unit can alarm and disable heat until the probe is reattached to the skin"], f: "In servo (skin) mode the heater is driven by the probe. A loose or detached probe can lead to overheating because the unit no longer sees a true skin temperature. The unsafe pattern is that the heater can overshoot because it no longer sees a true skin temperature. Check probe placement and mode, and follow the device's alarm behavior.", src: "fda-advice" },
    { id: "cb086", ages: 'both', topic: "troubleshooting", s: "A therapeutic ultrasound unit in physical therapy has a worn sound head and a failed completeness-of-output check. You should:", c: ["Continue treatments when you raise the output or intensity to make up for the worn applicator and cable", "Stop treatments until the applicator and output are corrected and a passing test is done", "Continue treatments when you post a note on the door and in the logbook", "Continue treatments when you check that the treatment timer or counter still works, and the clock advances"], f: "If the applicator or output is out of specification, treatments should stop until repair and a passing test. Stop treatments until the applicator and output are corrected and a passing test is done. Turning power up is not a safe fix.", src: "fda-ultrasound" },
    { id: "cb087", ages: 'both', topic: "troubleshooting", s: "A video integration system in an OR has no image on the main display, but the endoscope's local screen works. A useful path is:", c: ["Trace the endoscope lamp, light cable, and coupler, since the local image still works", "Trace the video route, cables, switcher, and display, because the local image is good", "Trace the table motor, drive, and its controller, if the local image still works", "Trace the ESU power, overlay, and its routing, after the local image still works"], f: "A good local image means the scope is producing video. Trace the video route, cables, switcher, and display, because the local image is good.", src: "fda-advice" },
    { id: "cb088", ages: 'both', topic: "troubleshooting", s: "A circulating nurse says a newly installed device does not work the way the previous unit did. The best first technical step is:", c: ["Ask what they expected, then replace the new device or module before checking settings or the manual", "Ask what was expected, confirm settings, and compare to the manual and a known-good unit", "Ask what they wanted, then change clinical set-points or defaults to match the previous unit", "Ask what was reported, then close the work order or ticket before checking settings and the manual"], f: "Many 'it does not work' calls are setup or a difference in workflow. Ask what was expected, confirm settings, and compare to the manual and a known-good unit, then repair if there is a real fault.", src: "fda-advice" },
    { id: "cb089", ages: 'both', topic: "troubleshooting", s: "A module in a physiologic monitor loses only the IBP channel, while ECG and NIBP still work. That pattern suggests:", c: ["A complete fault in the entire monitor chassis, its power supply, or its platform", "A local fault in that pressure channel, its cable, or its transducer interface", "A campus fault in that unit bus, its transfer switch, or its building supply", "A cuff fault in the NIBP channel, its hose, or its hose pack"], f: "When one parameter fails and others on the same monitor work, start with that channel and its accessories before replacing the entire platform. Start with a local fault in that pressure channel, its cable, or its transducer interface.", src: "fda-advice" },
    { id: "cb090", ages: 'both', topic: "troubleshooting", s: "You finish a repair on a life-support device. Before it returns to service you should:", c: ["Test a standby power-on only, and complete an abbreviated note on the ticket", "Test the functions that were affected, and complete the required documentation", "Test a standby power-on only, and complete the upcoming PM date in the CMMS", "Test a standby power-on only, and complete a return tag that skips the safety checks"], f: "Return-to-service needs verification of the repair, required safety and performance checks, and a record in the CMMS. Before return to service, test the functions that were affected and complete the required documentation. Skipping tests or records is not acceptable.", src: "fda-advice" },
    { id: "cb091", ages: 'both', topic: "safety", s: "A protective earth (ground) conductor on a medical device power cord is there mainly to:", c: ["Carry the normal load current in place of the hot and neutral conductors on that cord", "Carry a low-impedance fault current so protection can operate and touch voltage stays low", "Carry insulation duty so current-carrying conductors do not need jackets or shields", "Carry holding force so the plug cannot be pulled from the receptacle or strain relief"], f: "The grounding conductor is a safety path for fault current, not the normal load path. A protective earth conductor is there to carry a low-impedance fault current so protection can operate and touch voltage stays low. NFPA 99 and IEC 60601 address grounding and leakage in healthcare electrical systems and equipment; consult those standards for limits and methods.", src: "iec-60601", also: ["nfpa-99"], img: "img/cbet-plug.svg", imgAlt: "Front view of a US NEMA 5-15 receptacle with the ground hole down: the wider neutral slot is on the left, the narrower hot slot is on the right, and the ground hole is at the bottom.", imgAsk: true },
    { id: "cb092", ages: 'both', topic: "safety", s: "Macroshock and microshock are different because:", c: ["Microshock concerns static electricity that builds up on large appliances and clinic clothing in dry air", "Microshock concerns small currents that are dangerous if they reach the heart through a conductive path", "Microshock concerns radio-frequency interference used in telemetry systems and radio pagers on the unit", "Microshock concerns the same floor-receptacle leakage as a macroshock test on a branch circuit in that room"], f: "Macroshock is a shock through the intact body. Microshock refers to much smaller currents that can be hazardous if a conductive path (for example a catheter or lead) reaches the heart. Design and testing of patient connections take that risk into account. See IEC 60601 and NFPA 99 for the official limits and tests. Microshock concerns small currents that are dangerous if they reach the heart through a conductive path.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb093", ages: 'both', topic: "safety", s: "A GFCI device is intended to:", c: ["Open the branch if it detects a dangerous rise in patient leakage or earth current", "Open the circuit when it detects a dangerous imbalance between hot and neutral current", "Open the supply if it detects a missing equipment grounding conductor or bond", "Open the recorder if it detects a dangerous ECG amplitude or artifact during calibration"], f: "A GFCI compares outgoing and returning current and trips when the difference suggests leakage to ground. A GFCI is designed to open the circuit when it detects a dangerous imbalance between hot and neutral current. It is a personnel-protection device. It does not replace all other grounding and leakage requirements in medical equipment standards.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb094", ages: 'both', topic: "safety", s: "A Safety Data Sheet (SDS) is used to:", c: ["Describe a patient's diagnosis and how to enter it in the chart", "Describe chemical hazards and how to work with a product safely", "Describe a ventilator tidal volume and how to set it for an admission", "Describe an IP address and how to assign it to a monitor"], f: "The SDS (formerly MSDS) describes hazards, PPE, storage, and emergency actions for a chemical product. An SDS is used to describe chemical hazards and how to work with a product safely. It is not a medical record or a device setting sheet.", src: "osha-elec", also: ["nfpa-99"] },
    { id: "cb095", ages: 'both', topic: "safety", s: "A standard ionizing-radiation trefoil sign is meant to:", c: ["Warn of a supply storage closet off a public corridor", "Warn of a radiation hazard in that area or on that source", "Warn of a fire extinguisher of a different hazard class", "Warn of the unit's network name on a door or directory"], f: "The trefoil is used to warn of a radiation hazard in that area or on that source. Laser and MRI areas use their own distinctive warnings. Staff should heed posted signs and access rules.", src: "nfpa-99" },
    { id: "cb096", ages: 'both', topic: "safety", s: "Standard precautions in a healthcare facility include:", c: ["Perform hand hygiene only if gloves or gowns are already on for the task", "Perform hand hygiene and wear the PPE the task requires for that patient-care work", "Perform needle or lancet reuse to reduce the supply cost of the task", "Perform meal or break periods in a soiled utility area during the task"], f: "Standard precautions assume that blood and body fluids may be infectious. Perform hand hygiene and wear the PPE the task requires for that patient-care work, treating body fluids as potentially infectious, with safe sharps handling and cleaning, as taught by CDC and required in facilities.", src: "cdc-precautions", also: ["nfpa-99"] },
    { id: "cb097", ages: 'both', topic: "function", s: "CMS (Centers for Medicare and Medicaid Services) is important to hospitals in part because:", c: ["It manufactures infusion pumps and sells them to hospitals and clinics", "It sets Conditions of Participation and recognizes accrediting organizations", "It writes Ohm's law and adopts it as a regulation for safety programs", "It issues state PE licenses and grants them to clinical engineers and technicians"], f: "CMS sets Conditions of Participation and recognizes accrediting organizations, and it oversees federal healthcare payment programs. It is not a device maker or a PE board.", src: "cms-cops", also: ["nfpa-99"] },
    { id: "cb098", ages: 'both', topic: "safety", s: "Under IEC 60601-1, which applied-part type has the tightest patient leakage current limits?", c: ["Type B, for ungrounded-body applied parts", "Type CF, for direct cardiac applied parts", "Type BF, for body-floating applied parts", "Type A, an unofficial applied-part class outside IEC 60601-1"], f: "Type CF applied parts, intended for direct cardiac connection, have tighter patient-leakage limits than type B or BF in IEC 60601-1, in both normal and single-fault condition. Typical teaching values are on the order of 10 microamps for CF in normal condition, versus on the order of 100 microamps for B or BF. Confirm the figures in the current edition of the standard and on the device labeling. The tightest class is Type CF, for direct cardiac applied parts.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb099", ages: 'both', topic: "safety", s: "For a given applied-part type, IEC 60601-1 leakage current limits in single-fault condition, compared with normal condition, are:", c: ["Lower than in normal condition, and the device must be shut down immediately", "Higher than in normal condition, but still limited to a stated value", "Equal to those in normal condition for these leakage-current tests", "Open-ended versus normal condition, as long as a GFCI is installed on the branch"], f: "The standard allows a higher leakage current in a specified single-fault condition than in normal condition, but the current is still capped. Limits are higher than in normal condition, but still limited to a stated value. Type CF remains tighter than type BF in both conditions. Use the values and test setup from the edition and labeling that apply.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb100", ages: 'both', topic: "safety", s: "An MRI warning sign is posted because:", c: ["The area is a low-noise reading space, and ferromagnetic objects pose no special hazard", "The strong magnetic field pulls ferromagnetic objects and is a serious projectile hazard", "The area is a public waiting zone, and ferromagnetic objects pose no special hazard", "The sign is only a wayfinding marker, and ferromagnetic objects pose no special hazard"], f: "MRI systems have a strong magnetic field that pulls ferromagnetic objects and is a serious projectile hazard, along with other hazards (for example, implants and time-varying fields). Access and screening rules exist to prevent projectile and implant injuries.", src: "nfpa-99" },
  ]
});
